#!/usr/bin/env python3
"""Write-once review disposition and file seal; no network or runtime actions."""
import datetime, hashlib, json, platform, signal, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parent
REPO=ROOT.parents[2]
signal.alarm(30)
def binding(b): return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def canonical(v): return json.dumps(v,sort_keys=True,separators=(',',':')).encode()
def put(n,v):
    with (ROOT/n).open('x') as f:f.write(json.dumps(v,indent=2,sort_keys=True)+'\n')
v=json.loads((ROOT/'verification-result.json').read_bytes())
assert not (ROOT/'verify-v2.stderr').read_bytes() and (ROOT/'verify.stderr').read_bytes()
version=subprocess.run(['git','--version'],cwd=REPO,capture_output=True,check=True,timeout=10).stdout.decode().strip()
tree=subprocess.run(['git','--no-replace-objects','show','-s','--format=%T',v['source_revision']],cwd=REPO,capture_output=True,check=True,timeout=10).stdout.decode().strip()
assert tree==v['source_tree']
protected={'.github/workflows/hosted.yml':'fafd2560cc385a4113ea140bf2d4445d456e1f7f396539dfe2c3e7d6302e8b57','hosted/lib/mixer_hosted/browser_auth/store.ex':'8c314b1d3ce288a6dc617251233796bd0a9d8894247ccb15b101e1292e513299'}
for p,e in protected.items():assert binding((REPO/p).read_bytes())['sha256']==e
prior=REPO/'verification/github-delivery-runtime-followup/network-review'
prior_manifest=json.loads((prior/'packet-manifest.json').read_bytes())
assert binding((prior/'packet-manifest.json').read_bytes())['sha256']=='4ccc5ebe10600086473c96afd9aabf68ed63c46068419f5e599ac747f0d1800c'
for p,e in prior_manifest['files'].items():assert binding((prior/p).read_bytes())==e
put('verification-result-amendment.json',{'schema':1,'original_result':binding((ROOT/'verification-result.json').read_bytes()),'reason':'The original result hardcodes the first verifier command label; the actual passing command used the preserved v2 sibling.','actual_command':['python3','-B','verification/github-delivery-binary-export-and-ui/network-review/verify_artifact_v2.py'],'actual_source':binding((ROOT/'verify_artifact_v2.py').read_bytes()),'exit_code':0,'stdout':binding((ROOT/'verify-v2.stdout').read_bytes()),'stderr':binding((ROOT/'verify-v2.stderr').read_bytes()),'runtime_observations_unchanged':True})
decision={'schema':1,'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':{'model':'gpt-6-astra','reasoning_effort':'xhigh','role':'fresh difficult actual CI review'},'verdict':'binary-export-runtime-correction-passed-network-lane-blocked-by-postcompile-dependency-manifest','source_revision':v['source_revision'],'source_tree':tree,'run_id':v['run_id'],'run_attempt':1,'job_id':123044764614,'artifact_id':v['artifact_id'],'artifact_zip':v['zip'],'artifact_tree_digest_sha256':v['artifact_tree_digest_sha256'],'source_and_command_joins':{k:v[k] for k in ['source_files_verified','metadata_files_verified','helpers_verified','product_files_verified','product_digest','commands_verified','all_command_streams_retained_and_complete']},'actual_passed_scope':['111 collector pure controls','exact immutable images and all three container configurations','actual prepare and test mount policy','both seven-tool/VM/crypto/CA150 prerequisites','pinned TLS bootstrap and exclusive Rebar transfer/direct execution','exact pinned Hex and Rebar host exports, complete and retained','locked dependency preparation','1232-file prepared archive and exact restore','private offline test namespace and PostgreSQL16.15 nonroot/database scope','offline dependency compilation and warnings-as-errors product compilation'],'bootstrap_exports':v['bootstrap_exports'],'prepared_archive':v['prepared_archive'],'first_causal_failure':v['first_failure'],'product_methods_run':0,'complete_network_runtime_acceptance':False,'binary_export_correction_runtime_acceptance':True,'correction_selected_or_implemented':False,'recommended_next_scope':'Bounded source-supported distinction between generated compiler outputs and immutable dependency inputs; preserve original input equality, unknown-addition refusal and all existing guards. Do not blanket-ignore _build.','cleanup':v['cleanup'],'finalizer':v['finalizer'],'pending':v['not_run']+['fresh corrected actual CI and independent review','all native/process/custody/provider/customer/release/GA holds'],'limitations':v['limitations'],'protected_live_sources':protected,'previous_failure_packet':{'path':str(prior.relative_to(REPO)),'manifest':binding((prior/'packet-manifest.json').read_bytes()),'all_files_rehashed':len(prior_manifest['files'])},'tools':{'git':version,'python':platform.python_version(),'transport':'connected GitHub tools plus mcp__node_repl__js bounded fetch; no signed URL persisted'},'reviewer_errors_preserved':[{'source':'verify_artifact.py','stderr':'verify.stderr','failure':'reviewer expected bare capabilities; Docker records CAP_ prefixes','corrected_source':'verify_artifact_v2.py','corrected_stdout':'verify-v2.stdout','corrected_stderr':'verify-v2.stderr'},{'original_result':'verification-result.json','amendment':'verification-result-amendment.json','failure':'result command label retained first verifier path; actual passing v2 source hash was already correct'}],'commands':[{'argv':['python3','-B','verification/github-delivery-binary-export-and-ui/network-review/offline_preflight.py'],'exit_code':0,'alarm_seconds':40},{'argv':['python3','-B','verification/github-delivery-binary-export-and-ui/network-review/verify_artifact.py'],'exit_code':1,'alarm_seconds':50},{'argv':['python3','-B','verification/github-delivery-binary-export-and-ui/network-review/verify_artifact_v2.py'],'exit_code':0,'alarm_seconds':50},{'argv':['python3','-B','verification/github-delivery-binary-export-and-ui/network-review/seal.py'],'alarm_seconds':30}],'side_effects':{'canonical_edits_commit_push_dispatch_rerun':False,'local_compiler_container_PG_native_UI_capture':False,'held_process_probes':False,'private_FieldLog_access':False,'owned_runtime_started':False,'writes':'verification/github-delivery-binary-export-and-ui/network-review only'},'GA_accepted':False}
put('decision.json',decision)
files={}
for p in sorted(ROOT.rglob('*')):
    assert not p.is_symlink()
    if p.is_file():files[str(p.relative_to(ROOT))]=binding(p.read_bytes())
assert 'packet-manifest.json' not in files
packet={'schema':1,'scope':'actual failed-run review; bounded inert evidence and no canonical/runtime actions','files':files,'tree_digest_sha256':hashlib.sha256(canonical(files)).hexdigest()}
put('packet-manifest.json',packet)
print(json.dumps({'files':len(files),'tree_digest_sha256':packet['tree_digest_sha256'],'packet_manifest':binding((ROOT/'packet-manifest.json').read_bytes()),'decision':binding((ROOT/'decision.json').read_bytes()),'verdict':decision['verdict'],'product_methods_run':0},indent=2))
